SELECT tblEingabeUnGruppe.Gruppe, tblEingabeUnGruppe.Datum, tblEingabeUnGruppe.Zeit, tblEingabeUnGruppe.n AS Elementzahl, [Analyse Pure Brine Gruppe].[flow rate] AS FR, [Analyse Pure Brine Gruppe].[Na2SO4 Pb] AS cNa2SO4PB, [Analyse Anolyt Gruppe].[Na2SO4 An] AS cNa2SO4An, [Analyse Chlorgas Gruppe].[Cl2 + CO2 Cl] AS ConcCl2, [Analyse Chlorgas Gruppe].[O2 Cl] AS ConcO2, EtaNaClO3Ber([Analyse Anolyt Gruppe]![NaClO3 An],[VAnolyt],[Analyse Pure Brine Gruppe]![NaClO3 Pb],[Analyse Pure Brine Gruppe]![flow rate],[tblEingabeUnGruppe]![Elementzahl],[tblEingabeUnGruppe]![I Gesamt]) AS µNaClO3, EtaNaOClBer([Analyse Pure Brine Gruppe]![NaOCl An],[VAnolyt],[tblEingabeUnGruppe]![Elementzahl],[tblEingabeUnGruppe]![I Gesamt]) AS µNaOCl, EtaAlkaliBer([Analyse Pure Brine Gruppe]![NaOH Pb],[Analyse Pure Brine Gruppe]![flow rate],[tblEingabeUnGruppe]![Elementzahl],[tblEingabeUnGruppe]![I Gesamt]) AS µAlkali, EtaNa2CO3Ber([Analyse Pure Brine Gruppe]![Na2CO3 Pb],[Analyse Pure Brine Gruppe]![flow rate],[tblEingabeUnGruppe]![Elementzahl],[tblEingabeUnGruppe]![I Gesamt]) AS µNa2CO3, EtaHClBer([Analyse Pure Brine Gruppe]![HCl Pb],[Analyse Pure Brine Gruppe]![flow rate],[Analyse Anolyt Gruppe]![HCl An],[VAnolyt],[tblEingabeUnGruppe]![Elementzahl],[tblEingabeUnGruppe]![I Gesamt]) AS µHCl, EtaO2Ber([Analyse Chlorgas Gruppe]![ConcO2],[Analyse Chlorgas Gruppe]![ConcCl2],[µNaClO3],[µNaOCl]) AS µO2, EtaO2Ber([Analyse Chlorgas Gruppe]![O2 Cl],[Analyse Chlorgas Gruppe]![Cl2 + CO2 Cl],[µNaClO3],[µNaOCl]) AS µO2alt, EtaMembraneBer([µO2],[µNaClO3],[µNaOCl],[µHCl],[µNa2CO3],[µAlkali]) AS µNaOH, GEtGewAKF() AS CheckAKF, AktOClAnalyse() AS CheckClO, AktAnsaeurung() AS CheckAnsaeurung
FROM tblGewDaten INNER JOIN tblElektrolyseurbezeichnung ON tblGewDaten.IDElektrolyseurCEElektrolyseur = tblElektrolyseurbezeichnung.Nr, tblEingabeUnGruppe INNER JOIN (([Analyse Pure Brine Gruppe] INNER JOIN [Analyse Anolyt Gruppe] ON ([Analyse Pure Brine Gruppe].Datum = [Analyse Anolyt Gruppe].Datum) AND ([Analyse Pure Brine Gruppe].Gruppe = [Analyse Anolyt Gruppe].Gruppe)) INNER JOIN [Analyse Chlorgas Gruppe] ON ([Analyse Anolyt Gruppe].Datum = [Analyse Chlorgas Gruppe].Datum) AND ([Analyse Anolyt Gruppe].Gruppe = [Analyse Chlorgas Gruppe].Gruppe)) ON (tblEingabeUnGruppe.Datum = [Analyse Pure Brine Gruppe].Datum) AND (tblEingabeUnGruppe.Gruppe = [Analyse Pure Brine Gruppe].Gruppe)
WHERE (((tblEingabeUnGruppe.Datum)>=[tblGewDaten].[Anfangsdatum] And (tblEingabeUnGruppe.Datum)<=[tblGewDaten].[Enddatum]) AND ((VAnolytBer([Analyse Pure Brine Gruppe]![flow rate],[Analyse Pure Brine Gruppe]![Na2SO4 Pb],[Analyse Anolyt Gruppe]![Na2SO4 An]))<>(-1)) AND (([Analyse Chlorgas Gruppe].[Cl2 + CO2 Cl]) Is Not Null) AND (([Analyse Chlorgas Gruppe].[O2 Cl]) Is Not Null) AND ((EtaNaClO3Ber([Analyse Anolyt Gruppe]![NaClO3 An],[VAnolyt],[Analyse Pure Brine Gruppe]![NaClO3 Pb],[Analyse Pure Brine Gruppe]![flow rate],[tblEingabeUnGruppe]![Elementzahl],[tblEingabeUnGruppe]![I Gesamt]))<>(-1)) AND ((EtaNaOClBer([Analyse Pure Brine Gruppe]![NaOCl An],[VAnolyt],[tblEingabeUnGruppe]![Elementzahl],[tblEingabeUnGruppe]![I Gesamt]))<>(-1)) AND ((EtaAlkaliBer([Analyse Pure Brine Gruppe]![NaOH Pb],[Analyse Pure Brine Gruppe]![flow rate],[tblEingabeUnGruppe]![Elementzahl],[tblEingabeUnGruppe]![I Gesamt]))<>(-1)) AND ((EtaNa2CO3Ber([Analyse Pure Brine Gruppe]![Na2CO3 Pb],[Analyse Pure Brine Gruppe]![flow rate],[tblEingabeUnGruppe]![Elementzahl],[tblEingabeUnGruppe]![I Gesamt]))<>(-1)) AND ((EtaHClBer([Analyse Pure Brine Gruppe]![HCl Pb],[Analyse Pure Brine Gruppe]![flow rate],[Analyse Anolyt Gruppe]![HCl An],[VAnolyt],[tblEingabeUnGruppe]![Elementzahl],[tblEingabeUnGruppe]![I Gesamt]))<>(-1))) OR (((tblEingabeUnGruppe.Gruppe) Like (Select IDGruppe FROM tblGewDaten)))
ORDER BY tblEingabeUnGruppe.Datum;
